"use client";

import { RiCheckLine, RiEditBoxLine, RiShare2Line } from "@remixicon/react";
import { useState } from "react";
import { Dialog, Heading, Modal, ModalOverlay } from "react-aria-components";
import { Button } from "../../base/buttons/button";
import { Input } from "../../base/input/input";
import { ContributionsCard } from "../charts/contributions-card";
import { DailyHistoryCard } from "../charts/daily-history-card";
import { ProfileIdentityCard } from "../profile/profile-identity-card";
import {
  PROFILE_AGENT_MONTHS,
  PROFILE_TOKEN_DATA,
  PROFILE_CONTRIBUTION_RANGES,
} from "./profile-activity-data";
import { type TemplateShellProps, TemplateShell } from "./template-shell";

export interface AIProfileData {
  name: string;
  handle: string;
  cover: string;
  avatar?: string;
}
export interface AIProfileProps
  extends Pick<TemplateShellProps, "account" | "accounts" | "team" | "navigationItems"> {
  enableEditing?: boolean;
  enableSharing?: boolean;
  profile?: AIProfileData;
  onProfileChange?: (profile: AIProfileData) => void;
  contained?: boolean;
  className?: string;
}
const DEFAULT_PROFILE: AIProfileData = {
  name: "Jordan Morgan",
  handle: "jordan",
  cover: "/templates/ai-profile-cover.png",
};
export function AIProfile({
  profile: supplied,
  onProfileChange,
  contained,
  className,
  account,
  accounts,
  team,
  navigationItems,
  enableEditing = false,
  enableSharing = false,
}: AIProfileProps = {}) {
  const [local, setLocal] = useState(DEFAULT_PROFILE);
  const profile = supplied ?? local;
  const [draft, setDraft] = useState(profile);
  const [editing, setEditing] = useState(false);
  const [copied, setCopied] = useState(false);
  const [shareError, setShareError] = useState("");
  const share = async () => {
    try {
      await navigator.clipboard.writeText(window.location.href);
      setCopied(true);
    } catch {
      setShareError("Copy the URL from your browser’s address bar to share this profile.");
    }
  };
  return (
    <TemplateShell
      account={account}
      accounts={accounts}
      team={team}
      navigationItems={navigationItems}
      frameClassName="sm:p-6"
      navigationPlacement="overlay"
      title="Profile"
      selected="profile"
      hideHeader
      contained={contained}
      className={className}
      columnClassName="max-w-[680px] gap-4"
    >
      <ProfileIdentityCard
        {...profile}
        actions={
          <>
            <Button
              variant="secondary"
              size="small"
              leadingIcon={copied ? RiCheckLine : RiShare2Line}
              onClick={enableSharing ? share : undefined}
            >
              {copied ? "Copied" : "Share"}
            </Button>
            <Button
              variant="secondary"
              size="small"
              leadingIcon={RiEditBoxLine}
              onClick={
                enableEditing || onProfileChange
                  ? () => {
                      setDraft(profile);
                      setEditing(true);
                    }
                  : undefined
              }
            >
              Edit
            </Button>
          </>
        }
      >
        <ContributionsCard variant="profile" ranges={PROFILE_CONTRIBUTION_RANGES} />
        {shareError && (
          <p role="status" className="text-body-2-regular text-text-secondary">
            {shareError}
          </p>
        )}
      </ProfileIdentityCard>
      <DailyHistoryCard kind="agents" months={PROFILE_AGENT_MONTHS} />
      <DailyHistoryCard kind="tokens" data={PROFILE_TOKEN_DATA} />
      <ModalOverlay
        isOpen={editing}
        onOpenChange={setEditing}
        isDismissable
        className="fixed inset-0 z-50 flex items-center justify-center bg-background-modal-overlay p-4 backdrop-blur-sm"
      >
        <Modal className="w-full max-w-md rounded-3xl border border-border-button-default bg-background-primary-default p-6 shadow-dropdown">
          <Dialog className="outline-none">
            <form
              onSubmit={(event) => {
                event.preventDefault();
                const next = {
                  ...draft,
                  name: draft.name.trim(),
                  handle: draft.handle.replace(/^@/, "").trim(),
                };
                if (!next.name || !next.handle) return;
                setLocal(next);
                onProfileChange?.(next);
                setEditing(false);
              }}
              className="flex flex-col gap-4"
            >
              <Heading slot="title" className="text-title-3-medium text-text-primary">
                Edit profile
              </Heading>
              <Input
                label="Name"
                value={draft.name}
                onChange={(name) => setDraft({ ...draft, name })}
                isRequired
              />
              <Input
                label="Username"
                value={draft.handle}
                onChange={(handle) => setDraft({ ...draft, handle })}
                isRequired
              />
              <Input
                label="Cover image URL"
                value={draft.cover}
                onChange={(cover) => setDraft({ ...draft, cover })}
              />
              <div className="flex justify-end gap-2">
                <Button variant="secondary" onClick={() => setEditing(false)}>
                  Cancel
                </Button>
                <Button type="submit">Save changes</Button>
              </div>
            </form>
          </Dialog>
        </Modal>
      </ModalOverlay>
    </TemplateShell>
  );
}
